WITH RankedPosts AS (SELECT p.Id AS PostID, p.Title, p.Score, p.CreationDate, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS ScoreRank, p.OwnerUserId FROM Posts AS p WHERE p.PostTypeId = 1 AND NOT (p.Score IS NULL)), TopUsers AS (SELECT u.Id AS UserID, u.DisplayName, SUM(CASE WHEN NOT (p.Score IS NULL) THEN p.Score ELSE 0 END) AS TotalScore, COUNT(DISTINCT p.Id) AS TotalPosts FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId WHERE u.Reputation > 1000 GROUP BY u.Id, u.DisplayName), UserBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b WHERE b.Class = 1 GROUP BY b.UserId), ClosedPosts AS (SELECT ph.PostId, COUNT(CASE WHEN ph.PostHistoryTypeId = 10 THEN 1 END) AS CloseCount FROM PostHistory AS ph WHERE ph.CreationDate > CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR GROUP BY ph.PostId) SELECT u.DisplayName, u.TotalScore, u.TotalPosts, COALESCE(ub.BadgeNames, 'No Gold Badges') AS GoldBadges, COALESCE(cp.CloseCount, 0) AS ClosedPostsCount, rp.Title AS TopPostTitle, rp.Score AS TopPostScore FROM TopUsers AS u LEFT JOIN UserBadges AS ub ON u.UserID = ub.UserId LEFT JOIN ClosedPosts AS cp ON u.UserID = cp.PostId LEFT JOIN RankedPosts AS rp ON u.UserID = rp.OwnerUserId AND rp.ScoreRank = 1 WHERE u.TotalPosts > 5 ORDER BY u.TotalScore DESC NULLS FIRST, u.TotalPosts DESC NULLS FIRST